    'security_nudges_email_body' => '<p>Witaj,</p><p>Niektóre hasła, do których masz dostęp, wymagają uwagi:</p><ul><li><strong>#breached#</strong> naruszone</li><li><strong>#weak#</strong> słabe</li><li><strong>#reused#</strong> użyte ponownie</li><li><strong>#overdue#</strong> przeterminowane</li></ul><p>Zaloguj się i sprawdź swoje zabezpieczenia, aby je naprawić.</p><p><a href="#url#">Sprawdź moje zabezpieczenia</a></p><p><small>Ta wiadomość zawiera jedynie liczniki — żadne hasło ani nazwa elementu nie są dołączone.</small></p>',
    'settings_security_nudges' => 'Proaktywne wskazówki bezpieczeństwa',
    'settings_security_nudges_tip' => 'Włącz powiadomienia w aplikacji i oznaczenia przy hasłach, które są słabe, powtarzają się, wyciekły lub wymagają zmiany (wymagany dashboard kondycji bezpieczeństwa).',
    'settings_security_nudges_email' => 'Podsumowanie e-mail o zagrożonych hasłach',
    'settings_security_nudges_email_tip' => 'Okresowo wysyłaj każdemu użytkownikowi e‑mail z samym podsumowaniem liczby zagrożonych haseł (nie jest wysyłane żadne hasło ani nazwa elementu).',
    'settings_security_nudges_email_frequency' => 'Częstotliwość wysyłania podsumowań e-mail (w dniach)',
    'settings_security_nudges_email_frequency_tip' => 'Minimalny odstęp w dniach pomiędzy kolejnymi wiadomościami z podsumowaniem dla użytkownika.',
    'settings_security_nudges_stale' => 'Próg przedawnienia skanowania (w dniach)',
    'settings_security_nudges_stale_tip' => 'Jeśli ostatnie skanowanie wykonano dawniej niż podana liczba dni, użytkownik zobaczy przypomnienie o konieczności jego powtórzenia.',
    'ga_reset_blocked_by_admin' => 'Administrator wyłączył samodzielne resetowanie kodu 2FA. Poproś go o wysłanie nowego kodu.',
    'security_score_how_calculated' => 'Jak obliczany jest wynik?',
    'security_score_calc_intro' => 'Twój wynik mieści się w przedziale od 0 (najgorszy) do 100 (najlepszy). Odzwierciedla on odsetek haseł, do których masz dostęp do odczytu, dotkniętych tymi problemami – z uwzględnieniem wagi ich krytyczności:',
    'security_score_calc_not_counted' => 'Wyświetlane wyłącznie informacyjnie — nie wpływają na wynik:',
    'security_score_calc_scan_note' => 'Dane dotyczące powtórzonych haseł oraz wycieków staną się dokładne dopiero po uruchomieniu skanowania.',
    'restore_missing_sharekeys' => 'Przywracanie brakujących kluczy udostępniania',
    'restore_missing_sharekeys_tip' => 'To narzędzie wykrywa i odtwarza brakujące klucze udostępniania szyfrowania (elementy, pola niestandardowe i pliki). Użytkownicy bez klucza udostępniania widzą obiekt, ale nie mogą go odszyfrować (przekreślona ikona hasła). Analiza odbywa się w trybie tylko do odczytu. Naprawa najpierw przywraca brakujące wewnętrzne klucze referencyjne konta TP przy użyciu Twojego własnego konta, a następnie zadanie w tle dystrybuuje brakujące klucze do każdego użytkownika. Tworzone są tylko brakujące klucze – istniejące klucze nigdy nie są modyfikowane. Elementy osobiste są wykluczone.',
    'restore_missing_sharekeys_analyze' => 'Analizuj',
    'restore_missing_sharekeys_repair' => 'Napraw',
    'restore_missing_sharekeys_objects' => 'Obiekty',
    'restore_missing_sharekeys_missing_pairs' => 'Brakujące klucze udostępniania',
    'restore_missing_sharekeys_tp_missing' => 'Obiekty bez klucza referencyjnego',
    'restore_missing_sharekeys_unrecoverable' => 'Niemożliwe do automatycznego odzyskania',
    'restore_missing_sharekeys_no_missing' => 'Nie wykryto brakujących kluczy udostępniania. Naprawa nie jest potrzebna.',
    'restore_missing_sharekeys_found' => 'Wykryto brakujące klucze udostępniania. Kliknij przycisk Napraw, aby je odtworzyć.',
    'restore_missing_sharekeys_unrecoverable_tip' => 'Niektóre obiekty nie mają działającego klucza referencyjnego: ani wewnętrzne konto TP, ani Twoje konto nie może ich odszyfrować. Poproś użytkownika, który nadal może otworzyć te obiekty, o ich ponowne zapisanie. Spowoduje to odtworzenie kluczy dla wszystkich użytkowników.',
    'restore_missing_sharekeys_task_exists' => 'Zadanie naprawy kluczy udostępniania już oczekuje w kolejce lub jest wykonywane. Poczekaj na jego zakończenie.',
    'restore_missing_sharekeys_task_launched' => 'Zadanie naprawy zostało uruchomione. Brakujące klucze udostępniania są odtwarzane w tle. Postęp można śledzić na stronie Zadania.',
