    'leaver_risk_intro' => 'To konto mogło odczytywać te współdzielone dane logowania. Jeśli dana osoba opuszcza organizację, należy je zmienić. Elementy osobiste są wykluczone.',
    'leaver_risk_no_items' => 'To konto nie miało dostępu do żadnych współdzielonych danych logowania.',
