    'compliance_report_posture_summary' => 'Podsumowanie stanu zabezpieczeń sejfu',
    'compliance_report_posture_summary_tip' => 'Liczby haseł słabych, ujawnionych w wyciekach, nadmiernie udostępnionych i zaległych są obliczane na nowo przy każdym uruchomieniu. Liczby haseł używanych wielokrotnie i elementów osieroconych pochodzą z ostatniego pełnego skanowania (wymagają kontekstu umożliwiającego odszyfrowanie). Wyłącznie liczby, bez haseł i nazw elementów.',
