    'microlearning_title' => 'Porada dotycząca bezpieczeństwa',
    'microlearning_got_it' => 'Rozumiem — nie pokazuj ponownie',
    'microlearning_mute_all' => 'Wyłącz wszystkie porady',
    'microlearning_tip_unique_password' => 'Używaj innego hasła do każdego konta: jeśli dojdzie do wycieku w jednym serwisie, pozostałe konta pozostaną bezpieczne. Generator utworzy hasło jednym kliknięciem.',
    'microlearning_tip_passphrase' => 'Długość jest ważniejsza niż złożoność: fraza hasłowa złożona z kilku losowych słów jest łatwiejsza do zapamiętania i znacznie trudniejsza do złamania niż "P@ssw0rd1".',
    'microlearning_tip_secure_share' => 'Nigdy nie wysyłaj hasła e-mailem ani przez czat — takie kopie mogą pozostać na zawsze. Tymczasowy link wygasa i można go otworzyć tylko tyle razy, na ile zezwolisz.',
    'microlearning_tip_what_is_mfa' => 'Uwierzytelnianie wieloskładnikowe (MFA) zapewnia dodatkowe zabezpieczenie: nawet jeśli ktoś ukradnie Twoje hasło, nie zaloguje się bez Twojego telefonu. Włącz je w swoim profilu.',
    'microlearning_tip_reuse_risk' => 'Wielokrotne używanie jednego hasła jest jak używanie tego samego klucza do domu, samochodu i biura: jego utrata oznacza utratę wszystkiego. Panel stanu zabezpieczeń pokazuje, które z Twoich haseł są używane wielokrotnie.',
    'microlearning_tip_phishing' => 'TeamPass nigdy nie poprosi Cię o hasło w wiadomości e-mail. W razie wątpliwości nie klikaj linku — otwórz TeamPass z zakładki w przeglądarce.',
    'microlearning_tip_browser_extension' => 'Rozszerzenie przeglądarki uzupełnia hasła wyłącznie we właściwej witrynie, co zapewnia skuteczną ochronę przed podszywającymi się stronami phishingowymi. Skonfiguruj je w swoim profilu jednym kliknięciem.',
    'microlearning_tip_breach_check' => 'Hasło może być silne, a zarazem publicznie znane: bazy danych z wycieków zawierają miliardy rekordów. Od czasu do czasu sprawdzaj swoje wpisy pod kątem wycieków.',
    'microlearning_tip_expiry' => 'Najważniejsze dane logowania należy regularnie zmieniać. Foldery mogą mieć określony okres odnowienia. Elementy, dla których ten okres minął, są oznaczane w Twoim panelu.',
    'microlearning_tip_lock_leaving' => 'Odchodzisz od biurka? Zablokuj sesję (Win+L / Ctrl+Cmd+Q). Otwarty menedżer haseł na pozostawionym bez nadzoru ekranie niweczy wszystkie pozostałe zabezpieczenia.',
    'settings_micro_learning' => 'Kontekstowa mikroedukacja o bezpieczeństwie',
    'settings_micro_learning_tip' => 'Wyświetlaj krótkie, możliwe do zamknięcia wskazówki bezpieczeństwa w momencie wykonywania akcji (tworzenie elementu, udostępnianie sekretu...) oraz jedną poradę ogólną dziennie. Użytkownicy mogą zamknąć dowolną wskazówkę lub wyciszyć wszystkie — komunikaty nigdy nie blokują ekranu.',
    'palette_placeholder' => 'Szukaj w elementach, folderach, stronach...',
