    'licence_trial_no_grace_warning' => 'Licencja próbna nie ma okresu karencji: dostęp kończy się we wskazanym dniu. Nie obejmuje dodatkowych 15 dni, które subskrypcja zapewnia na jej odnowienie. Aby wykupić subskrypcję, napisz na adres',
