    'licence_trial_offline_title' => 'Poproś o okres próbny z innego komputera',
    'licence_trial_offline_intro' => 'Otwórz poniższy link na komputerze z dostępem do Internetu. Prowadzi on do strony na serwerze licencji, która po Twoim potwierdzeniu wykona żądanie niemożliwe do wysłania z tego serwera. Dodatkowy krok jest konieczny, ponieważ serwer licencji akceptuje to żądanie wyłącznie metodą POST, której zwykły link nie może użyć.',
    'licence_trial_offline_warning' => 'Link zawiera klucz licencyjny tej instancji. Traktuj go jako poufny: identyfikuje Twoją licencję, a strona, którą otwiera, jest jedynym miejscem, gdzie należy go wklejać.',
    'licence_trial_offline_contact_tip' => 'Wiadomość zostanie wysłana na ten adres, który link wskazuje jako kontakt dla okresu próbnego. Serwer licencji wyśle tam potwierdzenie. Adres musi należeć do domeny tej instancji:',
