    'licence_trial_offline_already_sent' => 'Link do złożenia prośby został wysłany dnia',
    'licence_trial_offline_no_feedback' => 'Ten serwer nie ma dostępu do Internetu i nie będzie mógł samodzielnie potwierdzić aktywacji. Nie stanowi to przeszkody: rozszerzenie przeglądarki sprawdza licencję bezpośrednio z przeglądarki, więc samo wykryje okres próbny po Twoim potwierdzeniu e-mailem.',
    'licence_trial_offline_email_subject' => 'TEAMPASS - Poproś o okres próbny rozszerzenia przeglądarki',
    'licence_trial_offline_email_body' => 'Witaj,<br><br>Ten serwer TeamPass (<strong>#tp_fqdn#</strong>) nie może połączyć się z serwerem licencji, dlatego nie mógł samodzielnie poprosić o okres próbny rozszerzenia przeglądarki.<br><br>Otwórz poniższy link na komputerze z dostępem do Internetu, a następnie potwierdź prośbę na stronie:<br><br><a href="#tp_trial_link#">#tp_trial_link#</a><br><br>Wiadomość potwierdzająca zostanie wtedy wysłana na adres <strong>#tp_contact_email#</strong>. Otwarcie zawartego w niej linku aktywuje 30-dniowy okres próbny.<br><br>Dwie ważne informacje:<br>- okres próbny jest przyznawany tylko raz dla danej domeny i produktu, bez możliwości ponownego przyznania;<br>- jeśli poprosisz o nową wiadomość potwierdzającą, poprzedni link przestanie działać.<br><br>Ten link zawiera klucz licencyjny Twojej instancji. Nie przekazuj go dalej.',
